ide="save"></i> Save Category</button></div></div></form></div></div>
<script>
(function(){
const modal=document.getElementById('categoryModal'),form=document.getElementById('categoryForm'),method=document.getElementById('formMethod'),mode=document.getElementById('formMode'),preview=document.getElementById('imagePreview'),imageInput=document.getElementById('categoryImage');
const storeUrl=@json(route('admin.categories.store'));
function openModal(){modal.classList.add('open');document.body.style.overflow='hidden';setTimeout(()=>document.getElementById('categoryName').focus(),50)}
function closeModal(){modal.classList.remove('open');document.body.style.overflow='';imageInput.value=''}
function setPreview(url){if(url){preview.src=url;preview.style.display='block'}else{preview.removeAttribute('src');preview.style.display='none'}}
function resetCreate(){form.reset();form.action=storeUrl;method.value='POST';mode.value='create';document.getElementById('editAction').value='';document.getElementById('modalTitle').textContent='Add New Category';document.getElementById('saveBtn').innerHTML='<i data-lucide="save"></i> Save Category';document.getElementById('categoryOrder').value='0';document.getElementById('categoryActive').checked=true;setPreview('');if(window.lucide)lucide.createIcons()}
document.getElementById('createBtn').addEventListener('click',()=>{resetCreate();openModal()});
document.querySelectorAll('.edit-btn').forEach(btn=>btn.addEventListener('click',()=>{resetCreate();form.action=btn.dataset.action;method.value='PUT';mode.value='edit';document.getElementById('editAction').value=btn.dataset.action;document.getElementById('modalTitle').textContent='Edit Category';document.getElementById('saveBtn').innerHTML='<i data-lucide="save"></i> Update Category';document.getElementById('categoryName').value=btn.dataset.name||'';document.getElementById('categoryDescription').value=btn.dataset.description||'';document.getElementById('categoryOrder').value=btn.dataset.order||'0';document.getElementById('categoryActive').checked=btn.dataset.active==='1';setPreview(btn.dataset.image||'');if(window.lucide)lucide.createIcons();openModal()}));
imageInput.addEventListener('change',()=>{const file=imageInput.files[0];if(file){setPreview(URL.createObjectURL(file))}});
document.getElementById('closeModal').addEventListener('click',closeModal);document.getElementById('cancelModal').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal.classList.contains('open'))closeModal();document.body.classList.remove('mobile-open')}});
document.querySelectorAll('.delete-form').forEach(f=>f.addEventListener('submit',e=>{if(!confirm('Delete category "'+f.dataset.name+'"? Categories with assigned products cannot be deleted.'))e.preventDefault()}));
const body=document.body,toggle=document.getElementById('sidebarToggle'),shade=document.getElementById('shade');
const mobile=()=>window.matchMedia('(max-width:820px)').matches;
try{if(!mobile()&&localStorage.getItem('brew_admin_sidebar_collapsed')==='1')body.classList.add('sidebar-collapsed')}catch(e){}
toggle.addEventListener('click',()=>{if(mobile()){const open=body.classList.toggle('mobile-open');toggle.setAttribute('aria-expanded',String(open))}else{const collapsed=body.classList.toggle('sidebar-collapsed');toggle.setAttribute('aria-expanded',String(!collapsed));try{localStorage.setItem('brew_admin_sidebar_collapsed',collapsed?'1':'0')}catch(e){}}});
shade.addEventListener('click',()=>body.classList.remove('mobile-open'));
@if($errors->any())
resetCreate();
@if(old('form_mode') === 'edit' && old('_method') === 'PUT')
// Reopen the corresponding edit dialog when validation fails.
const editAction=@json(old('_edit_action', ''));
const editButton=Array.from(document.querySelectorAll('.edit-btn')).find(b=>b.dataset.action===editAction);
if(editButton)editButton.click();
@endif
document.getElementById('categoryName').value=@json(old('name',''));
document.getElementById('categoryDescription').value=@json(old('description',''));
document.getElementById('categoryOrder').value=@json(old('sort_order',0));
document.getElementById('categoryActive').checked=@json((bool) old('is_active',false));
openModal();
@endif
if(window.lucide)lucide.createIcons();
})();
</script>
